INSERT INTO "catalog_products" ("slug","name","brand","category","collection","subcategory","series","color_name","description","bullets","spec_groups","price","list_price","image_id","image_ids","variant_options","variants","source_url","source_sku","rating","reviews","fixed_deal") VALUES ('siemens-eq900-iaroma-tq9x3b83-978092','Siemens EQ900 iAroma TQ9X3B83','Siemens','keuken','Koffie','Volautomatische espressomachines','Siemens EQ 900','Zilver','De Siemens EQ900 TQ9X3B83 past zich automatisch aan jouw koffiebonen aan. Het beanIdent systeem herkent de bonen. Daarna stemt de machine de maalgraad, doorlooptijd en temperatuur hierop af. Daarom haal je meer aroma uit je koffiebonen. Via het touchscreenkleurendisplay bedien je de machine gemakkelijk. Je bladert door het menu en kiest een koffiespecialiteit en instellingen. Je kiest uit meer dan 40 verschillende koffiespecialiteiten. Denk aan een krachtige espresso of een milde latte macchiato. Je stelt zelf de sterkte, hoeveelheid en temperatuur in. Daardoor smaakt elk kopje precies naar jouw wens.','["Melkreservoir zonder leidingen","41 koffierecepten","Met beanIdent systeem"]'::jsonb,'[{"title":"Product","specs":[["Fabrikantcode","TQ9X3B83"],["Merk","Siemens"],["Afhandeling van je defect","Bij jou thuis"],["Oude apparaat gratis retour","Ja"]]},{"title":"Algemene eigenschappen","specs":[["Type koffiezetapparaat","Volautomatische espressomachine"],["Type koffie/vulling","Koffiebonen"],["Inhoud bonenreservoir","375 g"],["Inhoud waterreservoir","2,3 l"],["Manier van afnemen waterreservoir","Uittillen"],["Heetwaterfunctie","Ja"],["Standby functie","Ja"]]},{"title":"Koffiebereiding","specs":[["Voorgeprogrammeerde koffievarianten","Americano, Cafe latte, Cappuccino, Cortado, Doppio, Dubbele Espresso, Espresso, Espresso macchiato, Flat white, Grote koffie, Hele koffiepot, IJskoffie, Latte macchiato, Lungo, Ristretto, Warme melk"],["Cold brew","Ja"],["Extractieprocess espresso","Gelijke druk"],["Aantal kopjes per zetbeurt","2"],["Instelbare koffiesterkte","Ja"],["Instelbaar koffievolume","Ja"],["Instelbare watertemperatuur","Ja"]]},{"title":"Melkbereiding","specs":[["Geschikt voor melk opschuimen","Ja"],["Manier van melkspecialiteit zetten","Automatisch met 1 druk op de knop"],["Melkopschuimmethode","Melkreservoir"],["Instelbaar melkvolume","Ja"],["2 melkspecialiteiten tegelijk","Ja"],["Inhoud melkreservoir","0,7 l"]]},{"title":"Extra opties","specs":[["Kopjes warmhoudplaat","Ja"],["Bediening","Touchscreen"],["Instelbare gebruikersprofielen","Ja"],["Aantal instelbare gebruikersprofielen","3"],["Koffiemachine bedienbaar via app","Direct mogelijk"],["Functies in app","Extra koffiespecialiteiten, Gebruikersprofielen, Onderhoudsinstructies, Recepten samenstellen"]]},{"title":"Onderhoud","specs":[["Hulp bij onderhoud","Veel hulp"],["Machine spoelen na gebruik","Automatisch"],["Type ontkalkingsprogramma","Melding en begeleiding"],["Tijdsduur ontkalken","20 min"],["Hoevaak ontkalken met waterfilter","1 keer per 2 maanden"],["Melkleidingen spoelen na gebruik","Automatisch"],["Zetgroep onderhoud","Handmatig afspoelen, Reinigingsprogramma uitvoeren"],["Vaatwasmachinebestendige onderdelen","Koffie-uitloop, Koffiedikbak, Lekbak, Melkreservoir, Melkslang, Opvangrooster"]]},{"title":"Fysieke eigenschappen","specs":[["Materiaal behuizing","RVS"],["Kleur","Zilver"],["Hoogte","39,2 cm"],["Breedte","31,5 cm"],["Diepte","47 cm"],["Gewicht","12 kg"]]},{"title":"Technische eigenschappen","specs":[["Materiaal waterleiding","Silicone"],["Materiaal maalschijven","Keramiek"],["Verwarmingssysteem koffie","Senso Flow"],["Pompdruk","19 bar"],["Vermogen","1500 W"]]}]'::jsonb,'663.00','1699.00','753735921','["753735921","64071970","1839638466","602797055","1368317367","1219582634","956421792","1647021268","414452313","1672497258","178734417","1170823268","1704495110","1659218724"]'::jsonb,'[]'::jsonb,'[]'::jsonb,'https://www.coolblue.nl/product/978092/','978092','4.6','19',true) ON CONFLICT ("slug") DO NOTHING;
