INSERT INTO "catalog_products" ("slug","name","brand","category","collection","subcategory","series","color_name","description","bullets","spec_groups","price","list_price","image_id","image_ids","variant_options","variants","source_url","source_sku","rating","reviews","fixed_deal") VALUES ('jura-z10-aluminium-black-eb-970358','JURA Z10 Aluminium Black (EB)','JURA','keuken','Koffie','Jura koffiemachines','JURA Z10','Aluminium Black','Met de JURA Z10 Aluminium Black (EB) zet je warme en koude koffiespecialiteiten met één druk op de knop. Dankzij het Cold Extraction Process maak je ook een verfrissende cold brew. De slimme bonenmaler past zich automatisch aan op jouw koffiekeuze. Zo wordt elke kop koffie gezet met de juiste maalgraad. Je stelt daar zelf niets voor in. Wil je iets anders dan koffie of koffie met een zoete smaak? Dan maak je met het chocolade opzetstuk romig chocolademelkschuim. Lekker voor warme chocolademelk of een zoete koffiedrank. De Z10 combineert slimme technologie met gemak. Je kiest uit veel soorten koffie en past alles aan naar jouw smaak. De aluminium behuizing geeft de machine een luxe uitstraling.','["Automatisch met 1 druk op de knop","Gemalen koffie, Koffiebonen","Inhoud bonenreservoir 280 g"]'::jsonb,'[{"title":"Product","specs":[["Fabrikantcode","15609"],["Merk","Jura"],["Afhandeling van je defect","Via Coolblue"],["Oude apparaat gratis retour","Ja"]]},{"title":"Algemene eigenschappen","specs":[["Type koffiezetapparaat","Volautomatische espressomachine"],["Type koffie/vulling","Gemalen koffie, Koffiebonen"],["Inhoud bonenreservoir","280 g"],["Dubbel bonenreservoir","Nee"],["Inhoud waterreservoir","2,4 l"],["Manier van afnemen waterreservoir","Uittillen"],["Heetwaterfunctie","Ja"],["Standby functie","Ja"]]},{"title":"Koffiebereiding","specs":[["Voorgeprogrammeerde koffievarianten","Americano, Cafe latte, Cappuccino, Chocolademelk, Cortado, Dubbele Espresso, Espresso, Espresso macchiato, Flat white, Grote koffie, IJskoffie, Latte macchiat