INSERT INTO "catalog_products" ("slug","name","brand","category","collection","subcategory","series","color_name","description","bullets","spec_groups","price","list_price","image_id","image_ids","variant_options","variants","source_url","source_sku","rating","reviews","fixed_deal") VALUES ('philips-5400-ep5447-90-lattego-866681','Philips 5400 EP5447/90 LatteGo','Philips','keuken','Koffie','Volautomatische espressomachines','Philips Latte Go','Zwart','<p>Kies uit 12 verschillende koffierecepten met de Philips 5400 EP5447/90. Je bedient het apparaat via een display met handige touchknoppen. Zo klik je op de icoontjes van de koffierecepten, zoals een flat white, cappuccino, espresso of americano. Daarnaast helpt het display jou tijdens het koffiezetten en onderhoud. Zo pas je een koffierecept helemaal aan naar je eigen smaak. Dit doe je via 5 aroma sterktes en 12 maalinstellingen. Je slaat je eigen recept op onder één van de 4 gebruikersprofielen. Na het gebruik van het LatteGo systeem, was je deze gemakkelijk af onder de kraan. Wanneer je het waterfilter gebruikt en op tijd vervangt, ontkalk je de machine slechts een keer er anderhalf jaar.</p>','["Gemiddeld werk aan onderhoud","Automatisch met 1 druk op de knop","Melkreservoir"]'::jsonb,'[{"title":"Product","specs":[["Fabrikantcode","EP5447/90"],["Merk","Philips"],["Afhandeling van je defect","Via Coolblue"],["Oude apparaat gratis retour","Ja"]]},{"title":"Algemene eigenschappen","specs":[["Type koffiezetapparaat","Volautomatische espressomachine"],["Type koffie/vulling","Gemalen koffie, Koffiebonen"],["Inhoud bonenreservoir","275 g"],["Dubbel bonenreservoir","Nee"],["Inhoud waterreservoir","1,8 l"],["Manier van afnemen waterreservoir","Uitschuiven"],["Heetwaterfunctie","Ja"],["Standby functie","Ja"]]},{"title":"Koffiebereiding","specs":[["Voorgeprogrammeerde koffievarianten","Americano, Cafe latte, Cappuccino, Espresso, Flat white, Koffie verkeerd, Latte macchiato, Lungo, Ristretto"],["Cold brew","Nee"],["Extractie