INSERT INTO "catalog_products" ("slug","name","brand","category","collection","subcategory","series","color_name","description","bullets","spec_groups","price","list_price","image_id","image_ids","variant_options","variants","source_url","source_sku","rating","reviews","fixed_deal") VALUES ('philips-5400-ep5447-90-lattego-onderhoudsset-986762','Philips 5400 EP5447/90 LatteGo + Onderhoudsset','Philips','keuken','Koffie','Volautomatische espressomachines','Philips Latte Go','Zwart','Met dit pakket zet je meteen een lekkere kop koffie en houd je de Philips 5400 EP5447\/90 LatteGo langer in topconditie. Met de espressomachine bereid je 12 koffiespecialiteiten, van een espresso tot een cappuccino of latte macchiato. Dankzij het LatteGo melksysteem schuimt de machine de melk automatisch op, zonder dat je losse slangetjes schoonmaakt. De keramische molen heeft 12 maalstanden, zodat je altijd de juiste maling voor jouw koffie kiest. Sla je favoriete recept op in 1 van de 4 gebruikersprofielen, zodat je koffie de volgende keer nog sneller klaarstaat. Voorkom met het Philips\/Saeco AquaClean waterfilter kalkaanslag in de machine. Je vervangt het filter iedere 3 maanden. Dankzij de goede werking van dit filter ontkalk je het apparaat slechts 1 keer per 1,5 jaar. Met de 2 filters uit dit pakket zit je dus voor langere tijd goed. Ontkalk je de espressomachine toch een keer? Gebruik dan de ontkalker uit dit pakket. Hiermee verwijder je kalk uit alle waterleidingen van het apparaat, zodat de kalk de smaak van je koffie niet aantast en de espressomachine langer meegaat.\r\n\r\n','[]'::jsonb,'[]'::jsonb,'191.00','454.00','1815098965','["1815098965","1460793","1873395","1460792","1460791","1779898","1460795","2164317","2164313","2164316","2164315","2164311","2164312","2164314","2164310","895019","895564","895568","895570","895033","1476183","895088","895597","895598","895089","895090","895091","895092","895093","895599"]'::jsonb,'[{"title":"Kies je koffiemachine","type":"choice","values":["Zet minder koffiespecialiteiten","Met onderhoudsset","Zet ook koude koffie specialiteiten","Zet meer koffiespecialiteiten"]},{"title":"Kies je kleur","type":"color","values":["Wit","Zwart"]}]'::jsonb,'[{"sku":"945962","name":"Philips LatteGo 5500 EP5547/90","values":{"Kies je koffiemachine":"Zet meer koffiespecialiteiten","Kies je kleur":"Zwart"},"price":"226.00","listPrice":"627.00","imageIds":["2226681","2226682","2226689","599425","687880559","2226691","2226690","2226686","2226683","2226684","2226685","2226688","2226687"]},{"sku":"866681","name":"Philips 5400 EP5447/90 LatteGo","values":{"Kies je koffiemachine":"Zet minder koffiespecialiteiten","Kies je kleur":"Zwart"},"price":"205.00","listPrice":"419.00","imageIds":["1460781","1460793","1873395","547368","593813","687880559","1460792","1460791","1779898","1460795","2164317","2164313","2164316","2164315","2164311","2164312","2164314","2164310"]},{"sku":"986762","name":"Philips 5400 EP5447/90 LatteGo + Onderhoudsset","values":{"Kies je koffiemachine":"Met onderhoudsset","Kies je kleur":"Zwart"},"price":"191.00","listPrice":"454.00","imageIds":["1815098965","1460793","1873395","1460792","1460791","1779898","1460795","2164317","2164313","2164316","2164315","2164311","2164312","2164314","2164310","895019","895564","895568","895570","895033","1476183","895088","895597","895598","895089","895090","895091","895092","895093","895599"]},{"sku":"945961","name":"Philips LatteGo 4400 EP4449/70","values":{"Kies je koffiemachine":"Zet ook koude koffie specialiteiten","Kies je kleur":"Zwart"},"price":"175.00","listPrice":"583.00","imageIds":["2025387","2025385","2025386","593810","687880559","2164300","2164294","2164301","2164298","2164297","2164296","2164293","2164295","2164299"]},{"sku":"958281","name":"Philips LatteGo 5500 EP5543/90","values":{"Kies je koffiemachine":"Zet meer koffiespecialiteiten","Kies je kleur":"Wit"},"price":"315.00","listPrice":"629.00","imageIds":["2124240","2124239","2124046","687880559","2124