INSERT INTO "catalog_products" ("slug","name","brand","category","collection","subcategory","series","color_name","description","bullets","spec_groups","price","list_price","image_id","image_ids","variant_options","variants","source_url","source_sku","rating","reviews","fixed_deal") VALUES ('philips-lattego-4400-ep4449-70-945961','Philips LatteGo 4400 EP4449/70','Philips','keuken','Koffie','Volautomatische espressomachines','Philips Latte Go','Zwart','Met de Philips 4400 EP4449/70 kies je uit verschillende koffierecepten via het display met touchknoppen. Zo kies je bijvoorbeeld uit een americano, lungo, cappuccino of een café au lait. Heb je geen zin in een hete kop koffie? Met deze machine zet je ook gemakkelijk een ijskoffie. In de avond zet je zonder moeite een kopje decaf, dankzij het vakje voor gemalen koffie. Wanneer je een koffiespecialiteit kiest, pas je deze naar je eigen smaak aan. Je slaat daarna je eigen recepten op onder één van de 3 gebruikersprofielen. Wanneer je het LatteGo systeem gebruikt, reinig je deze na gebruik gemakkelijk onder de kraan. Je ontkalkt de machine eens per anderhalf jaar dankzij het AquaClean filter.','["Gemiddelde hulp bij onderhoud","Automatisch met 1 druk op de knop","Met melkreservoir"]'::jsonb,'[{"title":"Product","specs":[["Fabrikantcode","EP4449/70"],["Merk","Philips"],["Afhandeling van je defect","Via Coolblue"],["Oude apparaat gratis retour","Ja"]]},{"title":"Algemene eigenschappen","specs":[["Type koffiezetapparaat","Volautomatische espressomachine"],["Type koffie/vulling","Gemalen koffie, Koffiebonen"],["Inhoud bonenreservoir","0,275 kg"],["Dubbel bonenreservoir","Nee"],["Inhoud waterreservoir","1,8 l"],["Manier van afnemen waterreservoir","Uittillen"],["Heetwaterfunctie","Ja"],["Standby functie","Ja"]]},{"title":"Koffiebereiding","specs":[["Voorgeprogrammeerde koffievarianten","Americano, Cafe latte, Cappuccino, Dubbele Espresso, Espresso, Grote koffie, IJskoffie, Latte macchiato, Lungo"],["Cold brew","Nee"],["Extracti