INSERT INTO "catalog_products" ("slug","name","brand","category","collection","subcategory","series","color_name","description","bullets","spec_groups","price","list_price","image_id","image_ids","variant_options","variants","source_url","source_sku","rating","reviews","fixed_deal") VALUES ('jura-e8-piano-black-ed-979188','JURA E8 Piano Black (ED)','JURA','keuken','Koffie','Jura koffiemachines','JURA E8','Piano Black','Met de JURA E8 Piano Black (ED) zet je verschillende koffies met één druk op de knop. Je kiest uit de Hot Brew, Light Brew of Sweet Foam stand. Zo maak je onder andere een sterke espresso, een milde koffie of een romige koffiespecialiteit. Je past het drankje aan naar jouw smaak. Dankzij de handige timer stel je vooraf in wanneer de machine koffie zet. Zo staat je koffie al klaar op het moment dat jij dat wilt. De ingebouwde Quality Assistant helpt je bij het onderhoud van de machine. Hij geeft aan wanneer je moet reinigen of ontkalken. Dat zorgt ervoor dat de machine goed blijft werken en je koffie lekker blijft smaken.','["Automatisch met 1 druk op de knop","Gemalen koffie, Koffiebonen","Inhoud bonenreservoir 280 g"]'::jsonb,'[{"title":"Product","specs":[["Fabrikantcode","15745"],["Merk","Jura"],["Afhandeling van je defect","On-site service"],["Oude apparaat gratis retour","Ja"]]},{"title":"Algemene eigenschappen","specs":[["Type koffiezetapparaat","Volautomatische espressomachine"],["Type koffie/vulling","Gemalen koffie, Koffiebonen"],["Inhoud bonenreservoir","280 g"],["Dubbel bonenreservoir","Nee"],["Inhoud waterreservoir","1,9 l"],["Manier van afnemen waterreservoir","Uittillen"],["Heetwaterfunctie","Ja"],["Standby functie","Ja"]]},{"title":"Koffiebereiding","specs":[["Voorgeprogrammeerde koffievarianten","Americano, Cafe latte, Cappuccino, Cortado, Dubbele Espresso, Espresso, Espresso macchiato, Flat white, Grote koffie, IJskoffie, Latte macchiato, Lungo"],["Cold brew","Nee"],["Extractieprocess espresso","Ongelijke druk"],["Aantal kopjes per zet