INSERT INTO "catalog_products" ("slug","name","brand","category","collection","subcategory","series","color_name","description","bullets","spec_groups","price","list_price","image_id","image_ids","variant_options","variants","source_url","source_sku","rating","reviews","fixed_deal") VALUES ('jura-c9-piano-black-ea-970363','JURA C9 Piano Black (EA)','JURA','keuken','Koffie','Jura koffiemachines','JURA koffiemachines','Piano Black','Met de Jura C9 Piano Black (EA) zet je elke koffiespecialiteit precies zoals jij die het liefst drinkt. Het display toont duidelijke keuzeopties, zodat je gemakkelijk het type koffie kiest. Sterkte, temperatuur en hoeveelheid stel je per kopje in. Dankzij de speciale zetmethode komt het water langer in contact met de koffie. Dat zorgt voor een vollere en rijkere smaak, vooral bij espresso. Er zijn 17 koffiespecialiteiten beschikbaar, van een krachtige espresso tot een romige cappuccino. De machine heeft een strak ontwerp dat goed past in elke keuken. Je zet gemakkelijk één of 2 kopjes koffie tegelijk. Dat is handig als je samen koffie drinkt.','["Automatisch met één druk op de knop","Gemalen koffie, Koffiebonen","Inhoud bonenreservoir 200 g"]'::jsonb,'[{"title":"Product","specs":[["Fabrikantcode","15753"],["Merk","Jura"],["Afhandeling van je defect","Via Coolblue"],["Oude apparaat gratis retour","Ja"]]},{"title":"Algemene eigenschappen","specs":[["Type koffiezetapparaat","Volautomatische espressomachine"],["Type koffie/vulling","Gemalen koffie, Koffiebonen"],["Inhoud bonenreservoir","200 g"],["Dubbel bonenreservoir","Nee"],["Inhoud waterreservoir","1,6 l"],["Manier van afnemen waterreservoir","Uittillen"],["Heetwaterfunctie","Ja"],["Standby functie","Ja"]]},{"title":"Koffiebereiding","specs":[["Voorgeprogrammeerde koffievarianten","Cappuccino, Cortado, Dubbele Espresso, Espresso, Espresso macchiato, Flat white, Grote koffie, Latte macchiato, Lungo"],["Cold brew","Nee"],["Extractieprocess espresso","Ongelijke druk"],["Aantal kopjes per zetb