INSERT INTO "catalog_products" ("slug","name","brand","category","collection","subcategory","series","color_name","description","bullets","spec_groups","price","list_price","image_id","image_ids","variant_options","variants","source_url","source_sku","rating","reviews","fixed_deal") VALUES ('delonghi-eletta-explore-ecam450-86-t-titanium-925202','De''Longhi Eletta Explore ECAM450.86.T Titanium','DeLonghi','keuken','Koffie','Volautomatische espressomachines','DeLonghi Eletta','Meerkleurig','De De''Longhi Eletta Explore ECAM450.86.T Titanium bereidt meer dan 50 koffierecepten. Zo kies je voor warme dranken, ijskoffies en zelfs een cold brew. De koffiemachine zet warme dranken via het LatteCrema Hot melksysteem. Dit melksysteem maakt een romig melkschuim op de juiste temperatuur. Met het LatteCrema Cold melksysteem maakt de machine koud melkschuim voor frisse ijskoffies. Wat hem uniek maakt, is de Cold Extraction Technology. Hiermee zet je met één druk op de knop een cold brew. Een cold brew is een koud gezette kop koffie. Denk hierbij aan een filterkoffie, maar dan ijskoud. Je bedient de machine via het touchscreen display of via de app. Zo krijg je toegang tot nog meer koffiespecialiteiten. Vandaag haast? Neem dan koffie in de meegeleverde thermosbeker mee met de To Go functie.','["Automatisch met één druk op de knop","Melkreservoir","Gemiddeld werk aan onderhoud","Goede stevigheid"]'::jsonb,'[{"title":"Product","specs":[["Fabrikantcode","0132217129"],["Merk","DeLonghi"],["Afhandeling van je defect","Via Coolblue"],["Oude apparaat gratis retour","Ja"]]},{"title":"Algemene eigenschappen","specs":[["Type koffiezetapparaat","Volautomatische espressomachine"],["Type koffie/vulling","Gemalen koffie, Koffiebonen"],["Inhoud bonenreservoir","300 g"],["Dubbel bonenreservoir","Nee"],["Inhoud waterreservoir","1,8 l"],["Manier van afnemen waterreservoir","Uitschuiven"],["Heetwaterfunctie","Ja"],["Standby functie","Ja"]]},{"title":"Koffiebereiding","specs":[["Voorgeprogrammeerde k