INSERT INTO "catalog_products" ("slug","name","brand","category","collection","subcategory","series","color_name","description","bullets","spec_groups","price","list_price","image_id","image_ids","variant_options","variants","source_url","source_sku","rating","reviews","fixed_deal") VALUES ('jura-w4-dark-inox-ea-965979','JURA W4 Dark Inox (EA)','JURA','keuken','Koffie','Jura koffiemachines','JURA koffiemachines','Brons','Met de JURA W4 Dark Inox (EA) zet je zwarte koffies op de werkplek. Het apparaat heeft een bonenreservoir van 500 gram en een waterreservoir van 3 liter. Je zet hiermee tot 30 koppen koffie achter elkaar, zonder dat je de machine bijvult. Kies uit 10 verschillende koffiespecialiteiten, zoals espresso, koffie en americano. Je past de koffie naar jouw smaak aan op het gebruiksvriendelijke display. De Professional Aroma Grinder maalt de bonen zeer precies, zodat de aroma''s uit de koffiebonen in elk kopje goed naar voren komen. Vervang je het waterfilter op tijd, dan ontkalk je het apparaat niet. Zo ben je weinig tijd kwijt aan onderhoud.','["Gemalen koffie, Koffiebonen","Schoonmaakindicator","Geen melkslang"]'::jsonb,'[{"title":"Product","specs":[["Fabrikantcode","15542"],["Merk","Jura"],["Afhandeling van je defect","Via Coolblue"],["Oude apparaat gratis retour","Ja"]]},{"title":"Algemene eigenschappen","specs":[["Type koffiezetapparaat","Volautomatische espressomachine"],["Type koffie/vulling","Gemalen koffie, Koffiebonen"],["Inhoud bonenreservoir","500 g"],["Dubbel bonenreservoir","Nee"],["Inhoud waterreservoir","3 l"],["Manier van afnemen waterreservoir","Uittillen"],["Heetwaterfunctie","Ja"],["Standby functie","Ja"]]},{"title":"Koffiebereiding","specs":[["Voorgeprogrammeerde koffievarianten","Americano, Doppio, Dubbele Espresso, Espresso, Grote koffie, Lungo"],["Cold brew","Nee"],["Extractieprocess espresso","Ongelijke druk"],["Aantal kopjes per zetbeurt","2"],["Instelbare koffiesterkte","Ja"],["Instelbaar koffievolume","Ja"],["Instelbare watertem