INSERT INTO "catalog_products" ("slug","name","brand","category","collection","subcategory","series","color_name","description","bullets","spec_groups","price","list_price","image_id","image_ids","variant_options","variants","source_url","source_sku","rating","reviews","fixed_deal") VALUES ('jura-w8-dark-inox-ea-953487','JURA W8 Dark Inox (EA)','JURA','keuken','Koffie','Jura koffiemachines','JURA koffiemachines','Grijs','Met de JURA W8 Dark Inox (EA) zet je zwarte koffies en melkspecialiteiten voor op de werkplek. Het koffiezetapparaat heeft een ruim bonenreservoir van 500 gram en waterreservoir van 3 liter. Hiermee zet je dagelijks 30 koffiespecialiteiten achter elkaar, zonder dat je de reservoirs bijvult. Met 17 verschillende koffiespecialiteiten is er voor ieder wat wils. Je zet espresso''s, cappuccino''s en heet water voor een kopje thee met één druk op de knop. De Professional Aroma Grinder maalt de bonen precies en snel. Hierdoor zijn alle koffies rijk van smaak en komen de koffie aroma''s extra goed naar voren. Je bent weinig tijd kwijt aan het onderhoud. Wanneer je het waterfilter op tijd vervangt, is ontkalken niet nodig.','["Gemalen koffie, Koffiebonen","Schoonmaakindicator","Melkslang"]'::jsonb,'[{"title":"Product","specs":[["Fabrikantcode","15550"],["Merk","Jura"],["Afhandeling van je defect","Via Coolblue"],["Oude apparaat gratis retour","Ja"]]},{"title":"Algemene eigenschappen","specs":[["Type koffiezetapparaat","Volautomatische espressomachine"],["Type koffie/vulling","Gemalen koffie, Koffiebonen"],["Inhoud bonenreservoir","500 g"],["Dubbel bonenreservoir","Nee"],["Inhoud waterreservoir","3 l"],["Manier van afnemen waterreservoir","Uittillen"],["Heetwaterfunctie","Ja"],["Standby functie","Ja"]]},{"title":"Koffiebereiding","specs":[["Voorgeprogrammeerde koffievarianten","Americano, Cappuccino, Cortado, Dubbele Espresso, Espresso, Espresso macchiato, Flat white, Grote koffie, Latte macchiato, Lungo"],["Extractieprocess espresso","Ongelijke druk"],["Aant